#include <bits/stdc++.h>
using namespace std;

int main() {
  int n;
  cin >> n;
  vector<int> x(n), y(n);
  for (int i = 0; i < n; ++i) {
    cin >> x[i] >> y[i];
  }

  for (int i = 0; i < n; ++i) {
    int max_dist = 0; //距離の2乗の最大値
    int idx = -1;     //距離が最大になる点の番号(0-indexed)
    for (int j = 0; j < n; ++j) {
      int dist = (x[i] - x[j]) * (x[i] - x[j]) +
                 (y[i] - y[j]) * (y[i] - y[j]); // 点i,jの距離の2乗
      if (max_dist < dist) {
        // 距離の最大値が更新された場合
        max_dist = dist;
        idx = j;
      }
    }
    cout << idx + 1 << endl;
  }
}
